"""Bygg en statisk app-portal fra en liste med private GitHub-repoer."""
import html
import json
import os
import re
import shutil
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path, PurePosixPath

TOKEN = os.environ.get("PRIVATE_REPOS_READ_TOKEN", "")
if not TOKEN:
    raise SystemExit("Mangler PRIVATE_REPOS_READ_TOKEN i GitHub Actions secrets.")

apps = json.loads(Path("apps.json").read_text(encoding="utf-8"))
site = Path("_site")
site.mkdir(exist_ok=True)
# Publish home-screen assets alongside the generated index.html.
for asset in ("manifest.json", "icon-192.png", "icon-512.png", "apple-touch-icon.png"):
    shutil.copyfile(Path(__file__).resolve().parent.parent / asset, site / asset)
ICONS = {
    "bubus-lyttetrening": "<path d=\"M5 14v-3a7 7 0 0 1 14 0v3\"/><rect x=\"3\" y=\"12\" width=\"4\" height=\"8\" rx=\"2\"/><rect x=\"17\" y=\"12\" width=\"4\" height=\"8\" rx=\"2\"/><path d=\"M10 10v5m4-7v9\"/>",
    "bubus-mengdeord": "<circle cx=\"6\" cy=\"6\" r=\"2\"/><circle cx=\"18\" cy=\"6\" r=\"2\"/><circle cx=\"6\" cy=\"18\" r=\"2\"/><circle cx=\"18\" cy=\"18\" r=\"2\"/><circle cx=\"12\" cy=\"12\" r=\"2\"/>",
    "bubus-norsk-musikkterminologi": "<path d=\"M9 18V6l11-3v12M9 9l11-3\"/><ellipse cx=\"6\" cy=\"18\" rx=\"3\" ry=\"2.5\"/><ellipse cx=\"17\" cy=\"15\" rx=\"3\" ry=\"2.5\"/>"
}

links = []
slugs = set()

for app in apps:
    slug = app["slug"]
    repo = app["repo"]
    source_file = app.get("file", "index.html")

    if not re.fullmatch(r"[a-z0-9-]+", slug) or slug in slugs:
        raise ValueError(f"Ugyldig eller duplisert slug: {slug}")
    if not re.fullmatch(r"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+", repo):
        raise ValueError(f"Ugyldig repo i apps.json: {repo}")
    if (not source_file or source_file.startswith("/")
            or ".." in PurePosixPath(source_file).parts
            or not source_file.lower().endswith((".html", ".htm"))):
        raise ValueError(f"Ugyldig HTML-fil i apps.json: {source_file}")
    slugs.add(slug)

    # GitHub Contents API leverer rå HTML-bytes. Repoets standardgren brukes.
    path = urllib.parse.quote(source_file, safe="/")
    url = f"https://api.github.com/repos/{repo}/contents/{path}"
    request = urllib.request.Request(url, headers={
        "Accept": "application/vnd.github.raw+json",
        "Authorization": f"Bearer {TOKEN}",
        "User-Agent": "personal-app-portal-builder",
        "X-GitHub-Api-Version": "2026-03-10",
    })
    try:
        with urllib.request.urlopen(request, timeout=45) as response:
            contents = response.read()
    except urllib.error.HTTPError as error:
        raise RuntimeError(
            f"Kan ikke hente {source_file} fra {repo} (HTTP {error.code}). "
            "Sjekk repo, filnavn og token-tilgang."
        ) from error

    destination = site / "apps" / slug / "index.html"
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_bytes(contents)
    print(f"Hentet {repo}/{source_file} -> {destination}")

    title = html.escape(app["title"])
    description = html.escape(app.get("description", ""))
    links.append(
        f'<a class="card" href="./apps/{slug}/">'
        f'<span class="app-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">{ICONS.get(slug, "")}</svg></span>'
        f'<strong>{title}</strong><span class="description">{description}</span>'
        '<span class="open-app" aria-hidden="true">Åpne appen <span>↗</span></span>'
        '</a>'
    )

cards = "\n".join(links)
homepage = """<!DOCTYPE html>
<html lang="nb">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="robots" content="noindex, nofollow">
  <meta name="theme-color" content="#fff5f8">
  <title>Bubus app-bibliotek</title>
  <link rel="manifest" href="./manifest.json">
  <link rel="icon" type="image/png" sizes="192x192" href="./icon-192.png">
  <link rel="icon" type="image/png" sizes="512x512" href="./icon-512.png">
  <link rel="apple-touch-icon" sizes="180x180" href="./apple-touch-icon.png">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@400;500;600&display=swap" rel="stylesheet">
  <style>
    :root { color-scheme: light; --ink:#593b4c; --muted:#795b6c; --rose:#a34269; }
    * { box-sizing: border-box; }
    body { margin:0; min-height:100vh; color:var(--ink); font:16px/1.6 'DM Sans','Segoe UI',sans-serif;
      background:radial-gradient(ellipse at 10% 0%,#fce1ec 0,transparent 48%),radial-gradient(ellipse at 100% 80%,#eee5fa 0,transparent 46%),#fff7fa; }
    main { max-width:1120px; margin:0 auto; padding:72px 28px 90px; }
    .brand { display:flex; flex-direction:column; align-items:center; text-align:center; margin-bottom:52px; gap:22px; }
    .brand-logo { display:block; width:154px; height:154px; border-radius:50%; box-shadow:0 8px 30px #8d476517; }
    h1 { font:500 clamp(2.3rem,5.8vw,4.2rem)/1.15 'Playfair Display',Georgia,serif; letter-spacing:-.035em; margin:0; }
    .grid { display:grid; gap:22px; grid-template-columns:repeat(3,minmax(0,1fr)); }
    .card { display:flex; flex-direction:column; align-items:flex-start; padding:30px 26px 25px; border:1px solid #eacbd9; border-radius:24px;
      text-decoration:none; color:inherit; background:#fffafc; box-shadow:0 8px 28px #a45a7610; transition:transform .18s,box-shadow .18s,border-color .18s; }
    .card:nth-child(2) { background:#fcf9ff; border-color:#e0d2ee; }
    .card:nth-child(3) { background:#fff8f5; border-color:#efd7cf; }
    .app-icon { width:60px; height:60px; display:grid; place-items:center; border-radius:19px; background:#f8dce8; color:#984264; margin-bottom:24px; }
    .app-icon svg { width:32px; height:32px; }
    .card:nth-child(2) .app-icon { background:#ece1f7; color:#80549b; }
    .card:nth-child(3) .app-icon { background:#fbe2db; color:#a65d54; }
    .card strong { font:500 1.65rem/1.3 'Playfair Display',Georgia,serif; letter-spacing:-.02em; overflow-wrap:anywhere; }
    .description { color:var(--muted); margin:12px 0 28px; }
    .open-app { display:flex; width:100%; justify-content:space-between; margin-top:auto; padding-top:18px; border-top:1px solid #ebdce3; color:var(--rose); font-size:.88rem; font-weight:600; }
    .open-app span { font-size:1.2rem; line-height:1; }
    .card:hover { transform:translateY(-5px); box-shadow:0 15px 34px #a45a7620; border-color:#c58ba5; }
    .card:focus-visible { outline:3px solid #9e416b; outline-offset:5px; }
    @media(max-width:800px) { .grid { grid-template-columns:1fr; max-width:540px; margin:auto; } main { padding:42px 20px 60px; } .brand { margin-bottom:34px; } .brand-logo { width:128px; height:128px; } .card { padding:25px; } }
    @media(prefers-reduced-motion:reduce) { .card { transition:none; } .card:hover { transform:none; } }
  </style>
</head>
<body>
  <main>
    <header class="brand">
      <img class="brand-logo" src="data:image/png;base64," alt="Bubus – kvinneportrett" width="154" height="154">
      <h1>Bubus app-bibliotek</h1>
    </header>
    <nav class="grid" aria-label="Bubus apper">%%CARDS%%</nav>
  </main>
</body>
</html>
"""
(site / "index.html").write_text(homepage.replace("%%CARDS%%", cards), encoding="utf-8")
(site / ".nojekyll").touch()
print(f"Bygget startside med {len(apps)} apper.")
